  }
  if (t.kind === 'br') return `<span class="t-br b${(t.depth ?? 0) % 3}">${esc}</span>`;
  return `<span class="t-${t.kind}">${esc}</span>`;
}

/**
 * HTML z kolorowaniem składni. `mark` (przesunięcia w źródle) zostaje
 * opakowany w znacznik błędu.
 */
export function highlightHtml(source: string, mark?: { start: number; end: number } | null): string {
  const tokens = highlightTokens(source);
  if (!mark) return tokens.map((t) => tokenHtml(t)).join('') + '\n';
  let html = '';
  const { start, end } = mark;
  let opened = false;
  for (const t of tokens) {
    const tEnd = t.start + t.text.length;
    if (tEnd <= start || t.start >= end) {
      if (!opened && t.start >= end && !html.includes('class="err-mark')) {
        html += '<span class="err-mark err-empty"></span>';
        opened = true;
      }
      html += tokenHtml(t);
      continue;
    }
    // Token zachodzi na zaznaczenie — dzielimy go na części.
    const a = Math.max(start, t.start) - t.start;
    const b = Math.min(end, tEnd) - t.start;
    if (a > 0) html += tokenHtml(t, t.text.slice(0, a));
    html += `<span class="err-mark">${tokenHtml(t, t.text.slice(a, b))}</span>`;
    opened = true;
    if (b < t.text.length) html += tokenHtml(t, t.text.slice(b));
  }
  if (!opened) html += '<span class="err-mark err-empty"></span>';
  return html + '\n';
}

