    });
  }

  private lineHeight(): number {
    return parseFloat(getComputedStyle(this.textarea).lineHeight) || 22;
  }

  private charWidth(): number {
    const probe = h('span', { class: 'ed-probe' }, 'MMMMMMMMMM');
    this.layer.append(probe);
