import type { Mode } from '../lang/ast';

export interface CommandDoc {
  names: string[];
  english: string[];
  arg: string;
  text: string;
  example: string;
  mode?: Mode;
}

export interface DocSection {
  id: string;
  title: string;
  intro?: string;
  commands?: CommandDoc[];
  /** Dowolne bloki: akapit HTML lub przykład kodu. */
