// Prosty serwer statyczny: serwuje katalog pod danym prefiksem (bez przepisywania ścieżek).
const [dir, prefix = '/', port = '4173'] = process.argv.slice(2);
Bun.serve({
  port: Number(port),
  async fetch(req) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith(prefix)) return new Response('not found', { status: 404 });
    let p = url.pathname.slice(prefix.length);
    if (p === '' || p.endsWith('/')) p += 'index.html';
    const f = Bun.file(`${dir}/${decodeURIComponent(p)}`);
    if (!(await f.exists())) return new Response('not found', { status: 404 });
    return new Response(f);
  },
});
console.log('serving', dir, 'at', prefix, port);
EOF
