[dl] = await Promise.all([page.waitForEvent('download'), page.locator('button:has-text("PNG")').click()]);
await dl.saveAs('/tmp/lm/export3d.png');
console.log('png3d bytes:', fs.statSync('/tmp/lm/export3d.png').size);
